interface.definition:
a!localVariables(
  local!bus: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3084520"(
    returnCDT: true,
    isActive: true
  ),
  local!eastBus: index(
    local!bus,
    wherecontains(
      #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206289",
      index(local!bus,"regionId",{})
    )
  ),
  local!westBus: index(
    local!bus,
    wherecontains(
      #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206296",
      index(local!bus,"regionId",{})
    )
  ),
  local!selectedRegion,
  local!selectedBU,
  local!rotationalAskPlan: #"_a-0000e825-ace1-8000-9c24-011c48011c48_6906867"(
    fiscalYear: ri!fiscalYear
  ),
  local!rotationalAskWestPlanIndex: wherecontains(
    #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206296",
    tointeger(index(local!rotationalAskPlan,"regionId",{}))
  ),
  local!rotationalAskWestPlan: index(
    local!rotationalAskPlan,
    local!rotationalAskWestPlanIndex,
    {}
  ),
  local!rotationalAskEastPlan: remove(
    local!rotationalAskPlan,
    local!rotationalAskWestPlanIndex
  ),
  local!westPlanned: sum(index(local!rotationalAskWestPlan,"plan",0)),
  local!eastPlanned: sum(index(local!rotationalAskEastPlan,"plan",0)),
  local!totalPlanned: local!eastPlanned + local!westPlanned,
  local!actualNominationsWithAsks: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6752972"(
    fiscalYear: ri!fiscalYear,
    posititionTypeId: #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699",
    subPositionTypeId: {
      #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4454622",
      #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4454629"
    },
    columns: {"askID","buID","statusId"}
  ).data,
  local!actualEastAsks: index(
    local!actualNominationsWithAsks,
    wherecontains(
      tointeger(index(local!eastBus,"buId",{})),
      tointeger(index(local!actualNominationsWithAsks,"buID",{}))
    )
  ),
  local!actualEastAsksCount: count(local!actualEastAsks),
  local!actualWestAsks: index(
    local!actualNominationsWithAsks,
    wherecontains(
      tointeger(index(local!westBus,"buId",{})),
      tointeger(index(local!actualNominationsWithAsks,"buID",{}))
    )
  ),
  local!actualWestAsksCount: length(local!actualWestAsks),
  local!completedWestAsksCount: length(
    wherecontains(
      #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5076350",
      tointeger(index(local!actualWestAsks,"statusId",{}))
    )
  ),
  local!inProcessWestAsksCount: local!actualWestAsksCount - local!completedWestAsksCount,
  local!completedEastAsksCount: length(
    wherecontains(
      #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5076350",
      tointeger(index(local!actualEastAsks,"statusId",{}))
    )
  ),
  local!inProcessEastAsksCount: local!actualEastAsksCount - local!completedEastAsksCount,
  local!totalActual: local!actualEastAsksCount + local!actualWestAsksCount,
  #"SYSTEM_SYSRULES_sectionLayout_v1"(
    contents: {
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: #"SYSTEM_SYSRULES_sectionLayout_v1"(
              contents: {
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: "FY " & ri!fiscalYear & " Rotationals",
                    color: "ACCENT",
                    size: "LARGE",
                    style: "STRONG"
                  ),
                  align: "CENTER"
                ),
                #"SYSTEM_SYSRULES_columnsLayout"(
                  columns: {
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: #"SYSTEM_SYSRULES_cardLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: local!totalPlanned,
                              color: "ACCENT",
                              size: "LARGE",
                              style: "STRONG"
                            ),
                            align: "CENTER"
                          ),
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: "ASK",
                              color: "ACCENT",
                              style: "STRONG"
                            ),
                            align: "CENTER"
                          )
                        }
                      )
                    ),
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: #"SYSTEM_SYSRULES_cardLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: local!totalActual,
                              color: if(
                                local!totalActual <> local!totalPlanned,
                                "NEGATIVE",
                                "POSITIVE"
                              ),
                              size: "LARGE",
                              style: "STRONG"
                            ),
                            align: "CENTER"
                          ),
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: "Confirmed/In Process",
                              color: "ACCENT",
                              style: "STRONG"
                            ),
                            align: "CENTER"
                          )
                        }
                      )
                    )
                  }
                )
              }
            ),
            width: "MEDIUM_PLUS"
          ),
          #"SYSTEM_SYSRULES_columnLayout"()
        }
      ),
      #"_a-0000e825-ace1-8000-9c24-011c48011c48_6779100"(
        message: "Select West or East below to show additional data."
      ),
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_cardLayout"(
                tooltip: "Select to show additional data",
                showBorder: false,
                link: #"SYSTEM_SYSRULES_dynamicLink"(
                  value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206296",
                  saveInto: {
                    local!selectedRegion,
                    a!save(local!selectedBU,null)
                  }
                ),
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: "West",
                      size: "MEDIUM_PLUS",
                      style: "STRONG"
                    ),
                    align: "CENTER"
                  ),
                  #"SYSTEM_SYSRULES_columnsLayout"(
                    columns: {
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: #"SYSTEM_SYSRULES_cardLayout"(
                          contents: {
                            #"SYSTEM_SYSRULES_richTextDisplayField"(
                              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                text: local!westPlanned,
                                color: "ACCENT",
                                size: "LARGE",
                                style: "STRONG"
                              ),
                              align: "CENTER"
                            ),
                            #"SYSTEM_SYSRULES_richTextDisplayField"(
                              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                text: "ASK",
                                color: "ACCENT",
                                style: "STRONG"
                              ),
                              align: "CENTER"
                            )
                          }
                        )
                      ),
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: #"SYSTEM_SYSRULES_cardLayout"(
                          contents: {
                            #"SYSTEM_SYSRULES_richTextDisplayField"(
                              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                text: local!actualWestAsksCount,
                                color: if(
                                  local!actualWestAsksCount <> local!westPlanned,
                                  "NEGATIVE",
                                  "POSITIVE"
                                ),
                                size: "LARGE",
                                style: "STRONG"
                              ),
                              align: "CENTER"
                            ),
                            #"SYSTEM_SYSRULES_richTextDisplayField"(
                              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                text: "Confirmed/In Process",
                                color: "ACCENT",
                                style: "STRONG"
                              ),
                              align: "CENTER"
                            )
                          }
                        )
                      )
                    }
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    align: "CENTER",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(text: "West - Rot", style: "STRONG")
                  )
                }
              ),
              #"SYSTEM_SYSRULES_pieChartField"(
                series: {
                  #"SYSTEM_SYSRULES_chartSeries"(
                    label: "Confirmed",
                    data: local!completedWestAsksCount
                  ),
                  #"SYSTEM_SYSRULES_chartSeries"(
                    label: "In Process",
                    data: local!inProcessWestAsksCount
                  ),
                  if(
                    local!westPlanned - local!actualWestAsksCount > 0,
                    #"SYSTEM_SYSRULES_chartSeries"(
                      label: "Open",
                      data: local!westPlanned - local!actualWestAsksCount
                    ),
                    {}
                  )
                },
                style: "PIE",
                colorScheme: #"SYSTEM_SYSRULES_colorSchemeCustom"(colors: { #"_a-0000e825-ace1-8000-9c24-011c48011c48_6777992", #"_a-0000e825-ace1-8000-9c24-011c48011c48_6778342", #"_a-0000e825-ace1-8000-9c24-011c48011c48_6778348" }),
                showDataLabels: true,
                seriesLabelStyle: "LEGEND",
                height: "MEDIUM"
              )
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_cardLayout"(
                showBorder: false,
                tooltip: "Select to show additional data",
                link: #"SYSTEM_SYSRULES_dynamicLink"(
                  value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206289",
                  saveInto: {
                    local!selectedRegion,
                    a!save(local!selectedBU,null)
                  }
                ),
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: "East",
                    size: "MEDIUM_PLUS",
                    style: "STRONG"
                  ),
                  align: "CENTER"
                ),
                  #"SYSTEM_SYSRULES_columnsLayout"(
                  columns: {
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: #"SYSTEM_SYSRULES_cardLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: local!eastPlanned,
                              color: "ACCENT",
                              size: "LARGE",
                              style: "STRONG"
                            ),
                            align: "CENTER"
                          ),
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: "ASK",
                              color: "ACCENT",
                              style: "STRONG"
                            ),
                            align: "CENTER"
                          )
                        }
                      )
                    ),
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: #"SYSTEM_SYSRULES_cardLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: local!actualEastAsksCount,
                              color: if(
                                local!actualEastAsksCount <> local!eastPlanned,
                                "NEGATIVE",
                                "POSITIVE"
                              ),
                              size: "LARGE",
                              style: "STRONG"
                            ),
                            align: "CENTER"
                          ),
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: "Confirmed/In Process",
                              color: "ACCENT",
                              style: "STRONG"
                            ),
                            align: "CENTER"
                          )
                        }
                      )
                    )
                  }
                ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                  align: "CENTER",
                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(text: "East - Rot", style: "STRONG")
                )
                }
              ),
              #"SYSTEM_SYSRULES_pieChartField"(
                  series: {
                    #"SYSTEM_SYSRULES_chartSeries"(
                      label: "Confirmed",
                      data: local!completedEastAsksCount
                    ),
                    #"SYSTEM_SYSRULES_chartSeries"(
                      label: "In Process",
                      data: local!inProcessEastAsksCount
                    ),
                    if(
                      local!eastPlanned - local!actualEastAsksCount > 0,
                      #"SYSTEM_SYSRULES_chartSeries"(
                        label: "Open",
                        data: local!eastPlanned - local!actualEastAsksCount
                      ),
                      {}
                    )
                  },
                  style: "PIE",
                  colorScheme: #"SYSTEM_SYSRULES_colorSchemeCustom"(colors: { #"_a-0000e825-ace1-8000-9c24-011c48011c48_6777992", #"_a-0000e825-ace1-8000-9c24-011c48011c48_6778342", #"_a-0000e825-ace1-8000-9c24-011c48011c48_6778348" }),
                  showDataLabels: true,
                  seriesLabelStyle: "LEGEND",
                  height: "MEDIUM"
                )
            }
          )
        }
      ),
      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6751668"(
        fiscalYear: ri!fiscalYear,
        region: local!selectedRegion,
        selectedBU: local!selectedBU,
        bus: if(
          tointeger(local!selectedRegion) = #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206296",
          local!westBus,
          local!eastBus
        ),
        rotationalAskPlan: if(
          tointeger(local!selectedRegion) = #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206296",
          local!rotationalAskWestPlan,
          local!rotationalAskEastPlan
        )
      )
    }
  )
)
